import csv
import io
import unittest

from exports import export_tickets


class ExportTicketsTests(unittest.TestCase):
    def test_empty_rows_still_has_header(self):
        self.assertEqual(
            export_tickets([]),
            b"\xef\xbb\xbfticket_id;summary;owner\r\n",
        )

    def test_order_encoding_and_extra_fields(self):
        result = export_tickets(
            [
                {
                    "owner": "Lin",
                    "summary": "修复;导出\n格式",
                    "ticket_id": 42,
                    "status": "closed",
                }
            ]
        )
        self.assertEqual(
            result,
            "\ufeffticket_id;summary;owner\r\n42;\"修复;导出\n格式\";Lin\r\n".encode(
                "utf-8"
            ),
        )

    def test_result_is_parseable_csv_bytes(self):
        result = export_tickets(
            [{"ticket_id": "T-1", "summary": 'say "hi"', "owner": "A"}]
        )
        rows = list(csv.DictReader(io.StringIO(result.decode("utf-8-sig")), delimiter=";"))
        self.assertEqual(rows, [{"ticket_id": "T-1", "summary": 'say "hi"', "owner": "A"}])


if __name__ == "__main__":
    unittest.main()

